# Cotizador: una sola cuenta. En la web (hetnacnc.com/cotizador/) se entra con la cuenta
# de la tienda ("Entrar con mi cuenta de hetnacnc.com") y el registro nuevo es el de la tienda.
# Uso: python3 aplicar_una_cuenta.py   (dentro de la carpeta del repo Cotizador)
import sys
def cambia(p, viejo, nuevo):
    s = open(p, encoding="utf-8").read()
    if s.count(viejo) != 1: sys.exit("No encontre el texto a cambiar en " + p)
    open(p, "w", encoding="utf-8").write(s.replace(viejo, nuevo))
